corporate_design.toad_component_blueprint:
canvas {
  size: 960px 580px;
  fill: #181D24;
  font-family: "Consolas, monospace";
}

>steel = #2B323D;
>safetyYellow = #FACC15;
>darkIron = #181D24;
>white = #FFFFFF;

rect #specSheet {
  at: center of canvas;
  size: 880px 480px;
  fill: >steel;
  stroke: #4B5563;
  stroke-width: 2px;
  radius: 2px;
}

text #companyTitle {
  at: top left of #specSheet offset 32px 28px;
  content: "KRUPPSTAHL // MASCHINENBAU AG • CNC-SERIE TITAN";
  font-size: 15px;
  font-weight: 700;
  color: >safetyYellow;
}

rect #warningStripe {
  at: below #companyTitle offset 16px;
  size: 816px 8px;
  fill: >safetyYellow;
}

text #machineName {
  at: below #warningStripe offset 28px;
  content: "TITANMILL 5000-HD // 5-ACHS PRÄZISION";
  font-size: 28px;
  font-weight: 700;
  color: >white;
}

text #techSpecs {
  at: below #machineName offset 16px;
  size: 760px;
  content: "SPINDELDREHZAHL: 24.000 U/MIN  •  TOLERANZ: ± 0.002 MM\nEILGANG X/Y/Z: 60 M/MIN  •  STEUERUNG: HEIDENHAIN TNC 640";
  font-size: 13px;
  color: #E5E7EB;
}
